+@Repository
+public class ExpLedgerRepositoryImpl implements ExpLedgerRepository {
+
+    private final JdbcTemplate jdbc;
+
+    public ExpLedgerRepositoryImpl(JdbcTemplate jdbc) {
+        this.jdbc = jdbc;
